WITH gaps AS (SELECT *, CASE WHEN LAG(txn_time) OVER (PARTITION BY account_id ORDER BY txn_time, id) IS NULL OR txn_time > LAG(txn_time) OVER (PARTITION BY account_id ORDER BY txn_time, id) + INTERVAL '60' DAY THEN 1 ELSE 0 END AS session_start_flag FROM transactions), islands AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY account_id ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM gaps) SELECT account_id, DATE_TRUNC('WEEK', txn_time) AS week_start, COUNT(*) AS event_count, COUNT(DISTINCT merchant) AS distinct_merchants FROM islands GROUP BY account_id, DATE_TRUNC('WEEK', txn_time) ORDER BY account_id NULLS LAST;
